-- Tulita: fictional demonstration catalog. NOT live or verified prices.
-- MySQL 8.0.16+ (CHECK constraints enforced). Import with a schema-admin account.
-- WARNING: this seed resets ONLY the Tulita tables and replaces their contents.
CREATE DATABASE IF NOT EXISTS tulita CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE tulita;
DROP TABLE IF EXISTS product_listings;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS stores;
CREATE TABLE products (
    id BIGINT PRIMARY KEY,
    name VARCHAR(180) NOT NULL,
    brand VARCHAR(80) NOT NULL,
    model VARCHAR(100) NOT NULL,
    category VARCHAR(40) NOT NULL,
    variant VARCHAR(120) NOT NULL,
    art VARCHAR(30) NOT NULL,
    INDEX idx_products_category (category),
    INDEX idx_products_name (name)
);
CREATE TABLE stores (
    id INT PRIMARY KEY,
    name VARCHAR(40) NOT NULL UNIQUE,
    website VARCHAR(255) NOT NULL
);
CREATE TABLE product_listings (
    id BIGINT PRIMARY KEY,
    product_id BIGINT NOT NULL,
    store_id INT NOT NULL,
    title VARCHAR(240) NOT NULL,
    model VARCHAR(100) NOT NULL,
    variant VARCHAR(120) NOT NULL,
    price DECIMAL(12,2) NOT NULL,
    mrp DECIMAL(12,2) NOT NULL,
    rating DECIMAL(2,1) NOT NULL,
    delivery_charge DECIMAL(10,2) NULL,
    delivery_estimate VARCHAR(60),
    available BOOLEAN NOT NULL DEFAULT TRUE,
    url VARCHAR(600),
    CONSTRAINT fk_listing_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    CONSTRAINT fk_listing_store FOREIGN KEY (store_id) REFERENCES stores(id),
    CONSTRAINT chk_price CHECK (price >= 0 AND mrp >= price),
    CONSTRAINT chk_rating CHECK (rating BETWEEN 0 AND 5),
    CONSTRAINT chk_delivery CHECK (delivery_charge IS NULL OR delivery_charge >= 0),
    UNIQUE KEY uq_product_store (product_id,store_id),
    INDEX idx_listing_store (store_id)
);
